37	    /** Left-pads every line with the given indent (empty lines stay empty). */
38	    public static List<String> indent(List<String> lines, int spaces) {
39	        String pad = " ".repeat(spaces);
40	        List<String> out = new ArrayList<>();
41	        for (String l : lines) out.add(l.isEmpty() ? l : pad + l);
42	        return out;
